<?php
require_once __DIR__.'/../app.php';require_once __DIR__.'/../ui.php';require_once __DIR__.'/../notifications_service.php';require_login();if(is_student()){if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')deny();redirect('student.php?view=notifications');}require_staff();
handle_post(function(){$id=positive_id($_POST['id']??null);$n=row('SELECT * FROM notifications WHERE id=? AND user_id=?',[$id,current_user()['id']]);if(!$n)deny();if($n['offering_id'])offering((int)$n['offering_id']);query('UPDATE notifications SET is_read=1 WHERE id=?',[$id]);},'notifications.php');
$data=user_notifications();page_start('Notifications','Account updates, grade workflow, deadlines, and follow-up reminders.');?><div class="two-column"><section class="panel"><h2>Reminders</h2><?php foreach($data['reminders']as $n):?><p class="notification"><a href="grades.php?offering_id=<?=(int)$n['offering_id']?>"><?=h($n['message'])?></a></p><?php endforeach;if(!$data['reminders'])echo '<p class="empty-state">No approaching deadlines.</p>';?></section><section class="panel"><h2>Account and class updates</h2><?php foreach($data['stored']as $n):?><article class="notification"><small><?=h($n['created_at'])?> · <?=$n['is_read']?'Read':'Unread'?></small><p><?=h($n['message'])?></p><?php if(!$n['is_read'])post_button('read',(int)$n['id'],'Mark read');?></article><?php endforeach;if(!$data['stored'])echo '<p class="empty-state">No notifications.</p>';?></section></div><?php page_end();
